&lt;p data-start=&quot;101&quot; data-end=&quot;215&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Join our fulfillment center team! Pay starting at $17/hr.&lt;/span&gt;&lt;/p&gt;
&lt;p data-start=&quot;101&quot; data-end=&quot;215&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;We’re hiring for:&lt;/span&gt;&lt;br data-start=&quot;152&quot; data-end=&quot;155&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;strong data-start=&quot;155&quot; data-end=&quot;215&quot;&gt;Seasonal &amp;amp; Permanent Fulfillment Associates&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;strong data-start=&quot;217&quot; data-end=&quot;244&quot;&gt;Hiring Event Details&lt;/strong&gt;&lt;/span&gt;&lt;br data-start=&quot;244&quot; data-end=&quot;247&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Wednesday, November 11&lt;/span&gt;&lt;br data-start=&quot;271&quot; data-end=&quot;274&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;8 AM – 10 AM&lt;/span&gt;&lt;br data-start=&quot;289&quot; data-end=&quot;292&quot;&gt;15521 Slover Ave, Fontana, CA 92337&lt;/p&gt;
